                        }
                      });
                    const on = a !== -1 && band !== null;
                    const opens = on && same(row[a], band.start);
                    const closes = on && same(row[b], band.end);
                    const after = band !== null && row[0] > band.end;
                    return (
                      <span
                        key={r}
