                              : "calc(var(--cell) * 7 - 2px)",
                          width: on
                            ? `calc(var(--cell) * ${b - a + 1} - ${opens ? INSET : "2px"} - ${closes ? INSET : "2px"})`
                            : "0px",
                          opacity: on ? 1 : 0,
