              <p
                className="mt-0.5 text-[11.5px] text-muted-foreground"
                aria-hidden="true"
              >
                <NumberRoll value={count} />{" "}
                <TextMorph>
                  {nights
                    ? count === 1
                      ? "night"
                      : "nights"
                    : count === 1
                      ? "day"
                      : "days"}
                </TextMorph>
              </p>
            </div>
            <div className="flex shrink-0 gap-1">
              <button
                type="button"
